window.SAGE_CHAPTERS = (window.SAGE_CHAPTERS || []).concat([
{
 id: "ppl-1", sage: "pippalada", n: 1, order: 4601, date: "2026-11-19",
 title: "The Child Left with the Trees", titleTe: "చెట్లకు అప్పగించిన బిడ్డ",
 src: "Brahma Purāṇa, Gautamī Māhātmya · Śiva Purāṇa, Śatarudra Saṃhitā",
 who: ["pippalada", "dadhichi", "suvarcha", "soma", "indra"],
 pages: [
  [
   ["p", "Some sages are born in palaces and some in āśramas full of chanting. {pippalada|Pippalāda} was born into grief. His story begins on the day his father died — and his father died by choice, for the sake of the whole world.", "కొందరు మహర్షులు రాజభవనాల్లో పుడతారు, కొందరు వేదఘోషతో నిండిన ఆశ్రమాల్లో పుడతారు. {pippalada|పిప్పలాదుడు} దుఃఖంలో పుట్టాడు. అతని కథ తండ్రి మరణించిన రోజునే మొదలవుతుంది — ఆ తండ్రి లోకమంతటి మేలు కోసం తనకు తానే ప్రాణం విడిచాడు."],
   ["p", "His father was {dadhichi|Dadhīci}, the great sage of the Sarasvatī's banks. When the demon Vṛtra had swallowed up the waters and the gods could not defeat him, {indra|Indra} and the gods came to Dadhīci and asked him for his bones, so that a weapon — the vajra — could be made from them. Dadhīci gave his body gladly.", "అతని తండ్రి సరస్వతీ తీరంలోని మహర్షి {dadhichi|దధీచి}. వృత్రాసురుడు నీళ్ళన్నిటినీ బంధించి, దేవతలు అతన్ని గెలవలేకపోయినప్పుడు, {indra|ఇంద్రుడు} దేవతలతో కలిసి దధీచి దగ్గరకు వచ్చి — వజ్రాయుధం చేయడానికి — ఆయన ఎముకలను అడిగాడు. దధీచి సంతోషంగా తన శరీరాన్ని దానం చేశాడు."],
   ["sglink", "Dadhīci's gift of his bones", "దధీచి ఎముకల దానం", "dd-5"]
  ],
  [
   ["h", "A mother comes home", "ఇంటికి తిరిగి వచ్చిన తల్లి"],
   ["p", "The Brahma Purāṇa, in its long section on the holy places of the Godāvarī, tells what happened next. Dadhīci's wife had been away from the āśrama when the gods came. The Śiva Purāṇa gives her name as {suvarcha|Suvarcā}. When she returned, her husband was gone; only the gods' errand and his empty āśrama remained.", "తర్వాత ఏం జరిగిందో గోదావరి తీర్థాల గురించిన బ్రహ్మ పురాణ భాగం చెబుతుంది. దేవతలు వచ్చినప్పుడు దధీచి భార్య ఆశ్రమంలో లేదు. శివ పురాణం ఆమె పేరు {suvarcha|సువర్చ} అని చెబుతుంది. ఆమె తిరిగి వచ్చేసరికి భర్త లేడు; దేవతల పని జరిగిపోయింది, ఆశ్రమం ఖాళీగా ఉంది."],
   ["p", "She was carrying Dadhīci's child. Her grief was so great that she resolved to follow her husband into death, as some wives of that age did. But she would not let the child die with her. The Purāṇas say that before she went, she brought the unborn child out of her womb, so that he at least could live.", "ఆమె దధీచి బిడ్డను మోస్తోంది. ఆమె దుఃఖం ఎంత గొప్పదంటే, ఆ కాలంలో కొందరు భార్యలు చేసినట్టు భర్తను అనుసరించి మరణించాలని నిశ్చయించుకుంది. కానీ బిడ్డను తనతో పాటు చావనివ్వలేదు. వెళ్ళే ముందే — కనీసం బిడ్డైనా బతకాలని — పుట్టని ఆ బిడ్డను గర్భం నుండి బయటకు తెచ్చిందని పురాణాలు చెబుతాయి."]
  ],
  [
   ["h", "“Look after him”", "“ఇతన్ని చూసుకోండి”"],
   ["p", "She laid the newborn at the foot of a great pippala tree — the sacred fig, the aśvattha — and spoke to the trees and plants of the forest: “You are his family now. Look after my son.” Then she entered the fire and followed her husband.", "ఆమె ఆ పసికందును ఒక పెద్ద రావిచెట్టు — పవిత్రమైన అశ్వత్థం — మొదట్లో పడుకోబెట్టి, అడవిలోని చెట్లతో, మొక్కలతో అంది: “ఇకపై మీరే వీడి కుటుంబం. నా కొడుకును చూసుకోండి.” తర్వాత అగ్నిలో ప్రవేశించి భర్తను అనుసరించింది."],
   ["p", "The trees heard her. They sheltered the child with their branches. And because no mother's milk was left for him, the trees turned to {soma|Soma}, the Moon, who is lord of all plants and herbs. The Moon gave them nectar, and with it they fed the baby. He grew strong eating the little fruits of the pippala — and so he was called Pippalāda, “the one who ate pippala.”", "చెట్లు ఆమె మాట విన్నాయి. తమ కొమ్మలతో బిడ్డకు నీడనిచ్చాయి. అతనికి తల్లి పాలు లేవు కాబట్టి, చెట్లు ఓషధులన్నిటికీ ప్రభువైన {soma|చంద్రుణ్ణి} ఆశ్రయించాయి. చంద్రుడు వాటికి అమృతం ఇచ్చాడు; దానితో అవి బిడ్డను పోషించాయి. రావి చెట్టు చిన్న పండ్లు తింటూ అతను బలంగా పెరిగాడు — అందుకే అతనికి ‘పిప్పలాదుడు’ — ‘రావి పండ్లు తిన్నవాడు’ — అనే పేరు వచ్చింది."],
   ["dyk", "🌳", "In Telugu the pippala is the రావి చెట్టు. Many Telugu villages still have a raised platform — a రావి అరుగు — around an old peepal, where people sit, talk and worship. Pippalāda grew up under one such tree.", "పిప్పలం అంటే తెలుగులో రావి చెట్టు. చాలా తెలుగు ఊళ్ళలో ఇప్పటికీ పాత రావిచెట్టు చుట్టూ అరుగు ఉంటుంది — అక్కడ జనం కూర్చుంటారు, కబుర్లు చెప్పుకుంటారు, పూజ చేస్తారు. పిప్పలాదుడు అలాంటి ఒక చెట్టు కిందే పెరిగాడు."],
   ["src", "Brahma Purāṇa, Gautamī Māhātmya (the Pippala tīrtha on the Godāvarī: Dadhīci's wife leaves the child with the trees and enters the fire; the Moon gives nectar; the name Pippalāda). Śiva Purāṇa, Śatarudra Saṃhitā (the Pippalāda story; the mother named Suvarcā). Dadhīci's gift is told in the Mahābhārata, Vana and Śānti Parvas, and in the Purāṇas.", "బ్రహ్మ పురాణం, గౌతమీ మాహాత్మ్యం (గోదావరి తీరంలోని పిప్పల తీర్థం: దధీచి భార్య బిడ్డను చెట్లకు అప్పగించి అగ్నిలో ప్రవేశించడం; చంద్రుడు అమృతం ఇవ్వడం; పిప్పలాదుడు అనే పేరు). శివ పురాణం, శతరుద్ర సంహిత (పిప్పలాదుని కథ; తల్లి పేరు సువర్చ). దధీచి దానం మహాభారతం వన, శాంతి పర్వాల్లో, పురాణాల్లో చెప్పబడింది."]
  ]
 ],
 remember: [
  ["{pippalada|Pippalāda} was the son of {dadhichi|Dadhīci}, who gave his bones to make the gods' vajra.", "{pippalada|పిప్పలాదుడు} — దేవతల వజ్రాయుధం కోసం ఎముకలు ఇచ్చిన {dadhichi|దధీచి} కుమారుడు."],
  ["His grieving mother left him with a pippala tree and followed her husband.", "దుఃఖంలో ఉన్న తల్లి అతన్ని రావిచెట్టుకు అప్పగించి భర్తను అనుసరించింది."],
  ["The trees, with nectar from the Moon, raised him; his name means “eater of pippala.”", "చంద్రుడిచ్చిన అమృతంతో చెట్లే అతన్ని పెంచాయి; ‘రావి పండ్లు తిన్నవాడు’ అని అతని పేరు అర్థం."]
 ],
 think: ["The trees and the Moon raised a child who had no one. Who are the people — or things — that have quietly “raised” you besides your parents?", "ఎవరూ లేని బిడ్డను చెట్లూ, చంద్రుడూ పెంచారు. తల్లిదండ్రులు కాకుండా మిమ్మల్ని నిశ్శబ్దంగా ‘పెంచిన’ మనుషులు — లేదా విషయాలు — ఏవి?"]
},
{
 id: "ppl-2", sage: "pippalada", n: 2, order: 4602, date: "2026-11-19",
 title: "The Boy Who Asked the Trees", titleTe: "చెట్లను ప్రశ్నించిన బాలుడు",
 src: "Brahma Purāṇa, Gautamī Māhātmya",
 who: ["pippalada", "dadhichi", "suvarcha", "indra"],
 pages: [
  [
   ["p", "{pippalada|Pippalāda} grew up in the forest with no human family around him. The trees were his shade and his home; the Moon's nectar and the figs were his food. He grew bright and strong, and he learned the forest's ways.", "{pippalada|పిప్పలాదుడు} చుట్టూ మనుషుల కుటుంబం లేకుండా అడవిలో పెరిగాడు. చెట్లే అతని నీడ, అతని ఇల్లు; చంద్రుని అమృతం, రావి పండ్లే అతని ఆహారం. తేజస్సుతో, బలంగా పెరిగాడు; అడవి తీరుతెన్నులు నేర్చుకున్నాడు."],
   ["p", "But a child begins to ask questions. One day he asked the trees: “Every creature I see has a father and a mother. The deer has its mother; the birds have their parents in the nest. Where are mine? Why am I alone?”", "కానీ బిడ్డ పెరిగేకొద్దీ ప్రశ్నలు అడగడం మొదలుపెడతాడు. ఒక రోజు అతను చెట్లను అడిగాడు: “నేను చూసే ప్రతి ప్రాణికీ తండ్రి, తల్లి ఉన్నారు. జింకకు తల్లి ఉంది; గూటిలో పక్షులకు అమ్మానాన్నలు ఉన్నారు. నావాళ్ళు ఎక్కడ? నేనెందుకు ఒంటరిగా ఉన్నాను?”"]
  ],
  [
   ["h", "The truth", "నిజం"],
   ["p", "The trees could not lie to him. They told him everything: that his father was the great sage {dadhichi|Dadhīci}; that the gods, in danger from Vṛtra, had come and asked for his father's bones; that his father had given up his life so that the vajra could be made; and that his mother, coming home to an empty āśrama, had left him with them and gone into the fire.", "చెట్లు అతనికి అబద్ధం చెప్పలేకపోయాయి. అంతా చెప్పాయి: అతని తండ్రి మహర్షి {dadhichi|దధీచి} అనీ; వృత్రుని వల్ల ఆపదలో పడిన దేవతలు వచ్చి తండ్రి ఎముకలు అడిగారనీ; వజ్రాయుధం తయారవడానికి తండ్రి ప్రాణం విడిచాడనీ; ఖాళీ ఆశ్రమానికి తిరిగి వచ్చిన తల్లి అతన్ని తమకు అప్పగించి అగ్నిలోకి వెళ్ళిపోయిందనీ."],
   ["p", "Pippalāda heard it in silence. Then something hot rose up in him. The gods had wanted to win their war. For that, his father had died; for that, his mother had died; for that, he had grown up an orphan under a tree. They had gone back to their heaven with their weapon and their victory, and no one had come to see what became of the child.", "పిప్పలాదుడు మౌనంగా విన్నాడు. తర్వాత అతనిలో ఏదో వేడిగా పొంగింది. దేవతలు తమ యుద్ధం గెలవాలనుకున్నారు. దాని కోసం తండ్రి చనిపోయాడు; దాని కోసం తల్లి చనిపోయింది; దాని కోసం తాను చెట్టు కింద అనాథగా పెరిగాడు. వాళ్ళు తమ ఆయుధంతో, తమ విజయంతో స్వర్గానికి వెళ్ళిపోయారు; బిడ్డ ఏమయ్యాడో చూడడానికి ఒక్కరూ రాలేదు."]
  ],
  [
   ["h", "A vow of anger", "కోపంతో చేసిన ప్రతిజ్ఞ"],
   ["p", "“They took my father for their own sake,” he said. “I will make the gods pay.” The boy who had been raised so gently by the trees now set his whole heart on one thing: the destruction of the gods who had taken his family from him.", "“తమ స్వార్థం కోసం నా తండ్రిని తీసుకున్నారు,” అన్నాడు. “దేవతలకు తగిన శాస్తి చేస్తాను.” చెట్లు ఎంతో ప్రేమగా పెంచిన ఆ బాలుడు ఇప్పుడు తన మనసంతా ఒకే విషయం మీద పెట్టాడు: తన కుటుంబాన్ని తన నుండి తీసుకెళ్ళిన దేవతల నాశనం."],
   ["p", "It is worth stopping here. The Purāṇa does not pretend Pippalāda was wrong to grieve. A child who has lost both parents has every reason for sorrow, and even for anger. The question the story will ask is a different one: what should a person do with an anger that has a real cause?", "ఇక్కడ ఒక్క క్షణం ఆగడం మంచిది. పిప్పలాదుడు దుఃఖించడం తప్పని పురాణం నటించదు. తల్లీ తండ్రీ ఇద్దరినీ పోగొట్టుకున్న బిడ్డకు దుఃఖపడడానికి, కోపపడడానికి కూడా పూర్తి కారణం ఉంది. కథ అడగబోయే ప్రశ్న వేరు: నిజమైన కారణం ఉన్న కోపంతో మనిషి ఏం చేయాలి?"],
   ["dyk", "🌊", "The Brahma Purāṇa's Gautamī Māhātmya is a long praise of the Godāvarī and of the holy places along its banks. Each place comes with its story — and Pippalāda's story is the story of the Pippala tīrtha.", "బ్రహ్మ పురాణంలోని గౌతమీ మాహాత్మ్యం గోదావరినీ, దాని ఒడ్డున ఉన్న పుణ్యక్షేత్రాలనూ కీర్తించే పెద్ద భాగం. ప్రతి క్షేత్రానికీ ఒక కథ ఉంటుంది — పిప్పలాదుని కథ పిప్పల తీర్థం కథ."],
   ["src", "Brahma Purāṇa, Gautamī Māhātmya (the Pippala tīrtha: the boy asks the trees about his parents, learns of his father's gift and his mother's death, and turns against the gods).", "బ్రహ్మ పురాణం, గౌతమీ మాహాత్మ్యం (పిప్పల తీర్థం: బాలుడు తల్లిదండ్రుల గురించి చెట్లను అడగడం, తండ్రి దానం, తల్లి మరణం తెలుసుకుని దేవతలపై కోపగించడం)."]
  ]
 ],
 remember: [
  ["{pippalada|Pippalāda} asked the trees why he had no parents.", "తనకు తల్లిదండ్రులు ఎందుకు లేరని {pippalada|పిప్పలాదుడు} చెట్లను అడిగాడు."],
  ["They told him the truth about {dadhichi|Dadhīci}'s gift and his mother's death.", "{dadhichi|దధీచి} దానం గురించీ, తల్లి మరణం గురించీ అవి నిజం చెప్పాయి."],
  ["Grief turned to anger, and he vowed to destroy the gods.", "దుఃఖం కోపంగా మారింది; దేవతలను నాశనం చేస్తానని ప్రతిజ్ఞ చేశాడు."]
 ],
 think: ["Pippalāda's anger had a real cause. Is anger always wrong? When does a fair anger turn into something harmful?", "పిప్పలాదుని కోపానికి నిజమైన కారణం ఉంది. కోపం ఎప్పుడూ తప్పేనా? న్యాయమైన కోపం ఎప్పుడు హానికరంగా మారుతుంది?"]
},
{
 id: "ppl-3", sage: "pippalada", n: 3, order: 4603, date: "2026-11-19",
 title: "The Power from Śiva's Eye", titleTe: "శివుని కంటి నుండి పుట్టిన శక్తి",
 src: "Brahma Purāṇa, Gautamī Māhātmya",
 who: ["pippalada", "shiva", "krtya", "dadhichi", "suvarcha", "indra"],
 pages: [
  [
   ["p", "{pippalada|Pippalāda} went to the banks of the Gautamī — the Godāvarī — and began a fierce tapas to {shiva|Śiva}. He was only a youth, but his determination was like his father's. At last Śiva appeared before him and offered him a boon.", "{pippalada|పిప్పలాదుడు} గౌతమీ — గోదావరి — తీరానికి వెళ్ళి {shiva|శివుని} కోసం ఘోర తపస్సు మొదలుపెట్టాడు. అతను ఇంకా యువకుడే, కానీ అతని పట్టుదల తండ్రి పట్టుదల లాంటిది. చివరకు శివుడు ప్రత్యక్షమై వరం కోరుకోమన్నాడు."],
   ["p", "Pippalāda asked for the power to destroy the gods. In the Purāṇa's telling, Śiva let him see his third eye — the eye of fire — and from that sight there arose a terrible destroying power, a {krtya|kṛtyā}. It stood before Pippalāda and asked: “What shall I do?” He answered: “Devour the gods who killed my father.”", "దేవతలను నాశనం చేసే శక్తిని పిప్పలాదుడు కోరాడు. పురాణ కథనం ప్రకారం శివుడు తన మూడవ కన్ను — అగ్నినేత్రం — చూపించాడు; ఆ చూపు నుండి భయంకరమైన సంహార శక్తి — ఒక {krtya|కృత్య} — పుట్టింది. అది పిప్పలాదుని ముందు నిలిచి అడిగింది: “ఏం చేయమంటావు?” అతను జవాబిచ్చాడు: “నా తండ్రిని చంపిన దేవతలను మింగేయి.”"]
  ],
  [
   ["h", "The fire turns back", "వెనక్కి తిరిగిన అగ్ని"],
   ["p", "But the kṛtyā turned first toward the one who stood nearest — Pippalāda himself. Terrified, he ran to Śiva: “I called this up to destroy the gods. Why does it come for me?”", "కానీ ఆ కృత్య ముందుగా దగ్గరగా ఉన్నవాని వైపు — పిప్పలాదుని వైపే — తిరిగింది. భయపడి అతను శివుని దగ్గరకు పరుగెత్తాడు: “దేవతలను నాశనం చేయడానికి దీన్ని పిలిచాను. ఇది నా మీదికి ఎందుకు వస్తోంది?”"],
   ["p", "The Purāṇa gives Śiva's answer as a teaching, in this spirit. The gods do not live only far away in heaven. They live in your own body: the Sun in your eyes, Agni in your speech, Indra in your hands, the Wind in your breath, the Moon in your mind. Every sense and limb is upheld by a god. “If the gods are destroyed,” Śiva told him, “your own body is destroyed first. Your anger cannot reach them without passing through you.”", "పురాణం శివుని జవాబును ఇలాంటి భావంతో ఒక బోధగా చెబుతుంది. దేవతలు దూరాన స్వర్గంలో మాత్రమే ఉండరు. నీ శరీరంలోనే ఉంటారు: నీ కళ్ళలో సూర్యుడు, నీ మాటలో అగ్ని, నీ చేతుల్లో ఇంద్రుడు, నీ శ్వాసలో వాయువు, నీ మనసులో చంద్రుడు. ప్రతి ఇంద్రియాన్నీ, ప్రతి అవయవాన్నీ ఒక దేవత నిలుపుతాడు. “దేవతలు నశిస్తే,” అని శివుడు చెప్పాడు, “ముందు నీ శరీరమే నశిస్తుంది. నీ కోపం నిన్ను దాటకుండా వారిని చేరలేదు.”"],
   ["dyk", "🔥", "This idea — that the gods of the world are also the powers inside the body — is very old. The Aitareya Upaniṣad tells how Fire became speech and entered the mouth, the Sun became sight and entered the eyes, the Wind became breath and entered the nose.", "లోకంలోని దేవతలే శరీరంలోని శక్తులు కూడా అనే భావం చాలా ప్రాచీనమైనది. అగ్ని మాటగా మారి నోటిలోకి, సూర్యుడు చూపుగా మారి కళ్ళలోకి, వాయువు శ్వాసగా మారి ముక్కులోకి ప్రవేశించారని ఐతరేయ ఉపనిషత్తు చెబుతుంది."]
  ],
  [
   ["h", "Mother and father in the sky", "ఆకాశంలో అమ్మానాన్న"],
   ["p", "Meanwhile the gods, frightened, had come to Śiva for shelter. And now, the Purāṇa says, Pippalāda was shown his father {dadhichi|Dadhīci} and his mother {suvarcha|Suvarcā}, shining in a heavenly chariot, at peace and full of honour. They spoke to their son. His father had given his body freely, with joy; no one had stolen it. They did not want revenge. They wanted their son to be at peace and to live a good life.", "ఇంతలో భయపడిన దేవతలు శివుని శరణు కోరి వచ్చారు. అప్పుడు — పురాణం చెబుతుంది — పిప్పలాదునికి తన తండ్రి {dadhichi|దధీచి}, తల్లి {suvarcha|సువర్చ} దివ్య విమానంలో ప్రశాంతంగా, గౌరవంతో ప్రకాశిస్తూ కనిపించారు. వాళ్ళు కొడుకుతో మాట్లాడారు. తండ్రి తన శరీరాన్ని ఇష్టంగా, ఆనందంగా ఇచ్చాడు; ఎవరూ దొంగిలించలేదు. వాళ్ళకు ప్రతీకారం అక్కర్లేదు. కొడుకు ప్రశాంతంగా, మంచి జీవితం గడపాలనే వాళ్ళ కోరిక."],
   ["p", "That was what finally cooled him. His anger had been for his parents' sake — and his parents did not want it. Pippalāda let it go. He forgave the gods, the kṛtyā was calmed, and the gods were safe.", "అదే చివరకు అతన్ని చల్లబరిచింది. అతని కోపం తల్లిదండ్రుల కోసమే — కానీ ఆ కోపం తల్లిదండ్రులకే అక్కర్లేదు. పిప్పలాదుడు దాన్ని వదిలేశాడు. దేవతలను క్షమించాడు; కృత్య శాంతించింది; దేవతలు క్షేమంగా ఉన్నారు."]
  ],
  [
   ["h", "The Pippala tīrtha", "పిప్పల తీర్థం"],
   ["p", "At the place on the Godāvarī where all this happened, the Purāṇa says, Śiva was worshipped as Pippaleśvara, and the place became a tīrtha. A bath there, it says, takes away the fire of anger and grief. The orphan who wanted to burn heaven became the reason for a place of peace.", "ఇదంతా జరిగిన గోదావరి తీరపు చోటులో శివుడు పిప్పలేశ్వరునిగా పూజలందుకున్నాడనీ, అది తీర్థంగా మారిందనీ పురాణం చెబుతుంది. అక్కడ స్నానం చేస్తే కోపాగ్ని, దుఃఖాగ్ని తొలగిపోతాయని అంటుంది. స్వర్గాన్ని కాల్చేయాలనుకున్న అనాథ బాలుడు శాంతి నెలవుకు కారణమయ్యాడు."],
   ["src", "Brahma Purāṇa, Gautamī Māhātmya (the Pippala tīrtha: Pippalāda's tapas on the Gautamī, the kṛtyā from Śiva's eye turning on him, Śiva's teaching that the gods dwell in the body, the vision of his parents, his forgiveness, and Śiva as Pippaleśvara). The gods entering the body: Aitareya Upaniṣad 1.2.", "బ్రహ్మ పురాణం, గౌతమీ మాహాత్మ్యం (పిప్పల తీర్థం: గౌతమీ తీరంలో పిప్పలాదుని తపస్సు, శివుని కంటి నుండి పుట్టిన కృత్య అతని మీదికే రావడం, దేవతలు శరీరంలోనే ఉంటారన్న శివ బోధ, తల్లిదండ్రుల దర్శనం, క్షమ, పిప్పలేశ్వరుడు). దేవతలు శరీరంలోకి ప్రవేశించడం: ఐతరేయ ఉపనిషత్తు 1.2."]
  ]
 ],
 remember: [
  ["{pippalada|Pippalāda}'s tapas won from {shiva|Śiva} a destroying power, a {krtya|kṛtyā} — but it turned first on him.", "{pippalada|పిప్పలాదుని} తపస్సుకు {shiva|శివుడు} ఒక సంహార శక్తిని — {krtya|కృత్యను} — ఇచ్చాడు; కానీ అది ముందు అతని మీదికే వచ్చింది."],
  ["Śiva taught that the gods live in our own senses; to destroy them is to destroy oneself.", "దేవతలు మన ఇంద్రియాల్లోనే ఉంటారనీ, వారిని నాశనం చేస్తే మనల్ని మనం నాశనం చేసుకుంటామనీ శివుడు బోధించాడు."],
  ["Seeing his parents at peace, he forgave the gods.", "తల్లిదండ్రులను ప్రశాంతంగా చూసి అతను దేవతలను క్షమించాడు."]
 ],
 think: ["The kṛtyā turned first on the one who called it up. Have you ever seen anger hurt the angry person before it hurt anyone else?", "కృత్య తనను పిలిచినవాని మీదికే ముందు తిరిగింది. కోపం ఇతరులను బాధించే ముందు కోపపడేవాణ్ణే బాధించడం మీరు ఎప్పుడైనా చూశారా?"]
},
{
 id: "ppl-4", sage: "pippalada", n: 4, order: 4604, date: "2026-11-19",
 title: "Śani Falls from the Sky — and Padmā", titleTe: "ఆకాశం నుండి పడిన శని — పద్మ కథ",
 src: "Śiva Purāṇa, Śatarudra Saṃhitā · later tellings",
 who: ["pippalada", "shani", "padma_p", "dharma", "shiva"],
 pages: [
  [
   ["p", "The Brahma Purāṇa's story ends with Pippalāda's forgiveness. The Śiva Purāṇa, a later work, tells his life in its own way. In its Śatarudra Saṃhitā — the book of Śiva's many forms and descents — {pippalada|Pippalāda} is counted as one of Śiva's own avatāras, born as Dadhīci's son. It adds two stories that are loved all over India, and especially in homes that worry about the planets.", "బ్రహ్మ పురాణ కథ పిప్పలాదుని క్షమతో ముగుస్తుంది. తరువాతి గ్రంథమైన శివ పురాణం అతని జీవితాన్ని తనదైన రీతిలో చెబుతుంది. దాని శతరుద్ర సంహితలో — శివుని అనేక రూపాలు, అవతారాల గ్రంథంలో — {pippalada|పిప్పలాదుడు} దధీచి కుమారునిగా పుట్టిన శివుని అవతారాల్లో ఒకటిగా లెక్కించబడ్డాడు. అది రెండు కథలను జోడిస్తుంది — భారతదేశమంతటా, ముఖ్యంగా గ్రహాల గురించి ఆందోళన పడే ఇళ్ళలో, ఎంతో ఇష్టంగా చెప్పుకునే కథలు."]
  ],
  [
   ["h", "Who was to blame?", "తప్పు ఎవరిది?"],
   ["p", "As the Śiva Purāṇa tells it, the grown Pippalāda asked why such misfortune had fallen on him as a newborn — father gone, mother gone, before he could even know them. He came to see that the heavy gaze of the planet {shani|Śani}, Saturn, had lain on his birth. In anger he looked up at Śani with the power of his tapas — and Śani fell from his place in the sky.", "శివ పురాణం చెప్పిన ప్రకారం, పెద్దవాడైన పిప్పలాదుడు — పుట్టగానే, తల్లిదండ్రులను తెలుసుకోకముందే వాళ్ళను పోగొట్టుకునేంత దురదృష్టం తనకెందుకు వచ్చిందని ఆలోచించాడు. తన జన్మ మీద {shani|శని} గ్రహం భారమైన దృష్టి పడిందని గ్రహించాడు. కోపంతో తన తపశ్శక్తితో శనివైపు చూశాడు — శని ఆకాశంలోని తన స్థానం నుండి కిందపడ్డాడు."],
   ["p", "The gods were alarmed, and they pleaded with Pippalāda to forgive Śani, who only does the work given to him. Pippalāda relented — but on a condition. Śani must never trouble young children. Some tellings say he made Śani promise not to afflict anyone under the age of sixteen. And whoever remembers Pippalāda's name, the Purāṇa says, will be eased from Śani's hardship.", "దేవతలు కంగారుపడి — తనకు అప్పగించిన పని మాత్రమే చేసే శనిని క్షమించమని పిప్పలాదుణ్ణి వేడుకున్నారు. పిప్పలాదుడు శాంతించాడు — కానీ ఒక షరతుతో. శని ఎన్నడూ చిన్న పిల్లలను బాధించకూడదు. పదహారేళ్ళ లోపు వారిని బాధించనని శనితో మాట తీసుకున్నాడని కొన్ని కథనాలు చెబుతాయి. పిప్పలాదుని పేరు స్మరించేవారికి శని బాధ తగ్గుతుందని పురాణం చెబుతుంది."],
   ["p", "Later folk tellings add that Śani was lamed by the fall, and that is why he walks slowly — the very name Śanaiścara means “the slow-moving one.” This detail belongs to popular telling.", "ఆ పడడంతో శనికి కాలు దెబ్బ తిన్నదనీ, అందుకే ఆయన నెమ్మదిగా నడుస్తాడనీ తరువాతి జానపద కథనాలు జోడిస్తాయి — ‘శనైశ్చరుడు’ అనే పేరుకే ‘నెమ్మదిగా నడిచేవాడు’ అని అర్థం. ఈ వివరం జనంలో ప్రచారంలో ఉన్న కథనానికి చెందినది."]
  ],
  [
   ["h", "Padmā", "పద్మ"],
   ["p", "The Śiva Purāṇa also says that Pippalāda, when he was already old, married {padma_p|Padmā}, a young princess, daughter of King Anaraṇya. Her father gave her, the story says, partly in fear of the sage's power. It was an unequal match by any measure. Yet Padmā served her husband with full devotion, and her faithfulness became famous.", "పిప్పలాదుడు వృద్ధుడైన తర్వాత అనరణ్య మహారాజు కుమార్తె, యువరాణి {padma_p|పద్మను} వివాహం చేసుకున్నాడని కూడా శివ పురాణం చెబుతుంది. మహర్షి శక్తికి భయపడి కూడా తండ్రి ఆమెను ఇచ్చాడని కథ అంటుంది. ఏ విధంగా చూసినా అది అసమాన సంబంధం. అయినా పద్మ భర్తను పూర్తి భక్తితో సేవించింది; ఆమె పాతివ్రత్యం ప్రసిద్ధమైంది."],
   ["p", "So famous that {dharma|Dharma} himself came to test it. He came disguised as a handsome young king and tried to turn her heart away from her old husband. Padmā refused him sharply and spoke hard words to him in her anger. Then Dharma showed his true form, praised her, and blessed the couple. The tellings differ on the details of what she said and what followed, and this whole episode belongs to the later Purāṇas.", "ఎంత ప్రసిద్ధమంటే — స్వయంగా {dharma|ధర్మదేవతే} దాన్ని పరీక్షించడానికి వచ్చాడు. అందమైన యువరాజు వేషంలో వచ్చి, ఆమె మనసును వృద్ధుడైన భర్త నుండి మళ్ళించడానికి ప్రయత్నించాడు. పద్మ కఠినంగా తిరస్కరించి, కోపంతో అతనికి గట్టి మాటలు అంది. అప్పుడు ధర్మదేవత తన నిజరూపం చూపి, ఆమెను పొగిడి, దంపతులను ఆశీర్వదించాడు. ఆమె అన్న మాటల వివరాలూ, తర్వాత జరిగినదీ కథనాలను బట్టి మారుతాయి; ఈ ఘట్టమంతా తరువాతి పురాణాలకు చెందినది."],
   ["dyk", "🪐", "In many Telugu homes, during a hard period of Śani (ఏలినాటి శని), people say a short prayer remembering Pippalāda along with other sages, and pour oil on a Śani image on Saturdays. The story of Pippalāda and Śani is the reason his name appears there.", "చాలా తెలుగు ఇళ్ళలో ఏలినాటి శని వంటి కష్టకాలంలో ఇతర మహర్షులతో పాటు పిప్పలాదుణ్ణి స్మరించే చిన్న ప్రార్థన చెబుతారు; శనివారాలు శని విగ్రహానికి నూనె పోస్తారు. అక్కడ పిప్పలాదుని పేరు రావడానికి కారణం ఈ కథే."],
   ["src", "Śiva Purāṇa, Śatarudra Saṃhitā (Pippalāda as an avatāra of Śiva; Śani made to fall and the promise about children; Padmā, daughter of Anaraṇya, and Dharma's test). The age of sixteen and Śani's lameness are found in later and popular tellings, which vary. The Brahma Purāṇa does not tell these episodes.", "శివ పురాణం, శతరుద్ర సంహిత (పిప్పలాదుడు శివావతారం; శని పతనం, పిల్లల గురించిన వాగ్దానం; అనరణ్యుని కుమార్తె పద్మ, ధర్మదేవత పరీక్ష). పదహారేళ్ళ వయసు, శని కుంటితనం తరువాతి, జనప్రచార కథనాల్లో కనిపిస్తాయి; అవి మారుతూ ఉంటాయి. బ్రహ్మ పురాణం ఈ ఘట్టాలు చెప్పదు."]
  ]
 ],
 remember: [
  ["The Śiva Purāṇa counts {pippalada|Pippalāda} as an avatāra of Śiva.", "శివ పురాణం {pippalada|పిప్పలాదుణ్ణి} శివావతారంగా లెక్కిస్తుంది."],
  ["He made {shani|Śani} fall, then forgave him on condition that he never trouble young children.", "{shani|శనిని} పడేలా చేసి, చిన్న పిల్లలను ఎన్నడూ బాధించకూడదనే షరతుతో క్షమించాడు."],
  ["His wife {padma_p|Padmā} stood firm when {dharma|Dharma} came in disguise to test her.", "ధర్మదేవత మారువేషంలో పరీక్షించడానికి వచ్చినప్పుడు అతని భార్య {padma_p|పద్మ} చలించలేదు."]
 ],
 think: ["Pippalāda forgave Śani, but asked for protection for children. When we forgive someone, can we still ask that the harm not happen again?", "పిప్పలాదుడు శనిని క్షమించాడు, కానీ పిల్లలకు రక్షణ కోరాడు. ఎవరినైనా క్షమించినప్పుడు, ఆ హాని మళ్ళీ జరగకూడదని అడగవచ్చా?"]
},
{
 id: "ppl-5", sage: "pippalada", n: 5, order: 4605, date: "2026-11-19",
 title: "Six Seekers and a Year of Waiting", titleTe: "ఆరుగురు జిజ్ఞాసువులు — ఏడాది నిరీక్షణ",
 src: "Praśna Upaniṣad 1.1–2",
 who: ["pippalada", "sukesha", "satyakama_s", "sauryayani", "kausalya_a", "bhargava_v", "kabandhi", "shankara"],
 pages: [
  [
   ["p", "Now we come to the oldest and most important place where Pippalāda's name is found: the Praśna Upaniṣad, the “Upaniṣad of Questions”, which belongs to the Atharvaveda. Here there are no trees, no kṛtyā, no Śani. There is only a great teacher, six students, and six questions about the deepest things.", "ఇప్పుడు పిప్పలాదుని పేరు కనిపించే అత్యంత ప్రాచీనమైన, ముఖ్యమైన చోటుకు వచ్చాం: అథర్వవేదానికి చెందిన ప్రశ్నోపనిషత్తు — ‘ప్రశ్నల ఉపనిషత్తు’. ఇక్కడ చెట్లు లేవు, కృత్య లేదు, శని లేడు. ఒక గొప్ప గురువు, ఆరుగురు శిష్యులు, అత్యంత లోతైన విషయాల గురించి ఆరు ప్రశ్నలు — అంతే."],
   ["p", "The Upaniṣad does not tell us whose son this teacher was. Tradition joins him with Dadhīci's son; some modern readers think they may be different men who shared a name. We tell both, as the texts do, and let you hold them together.", "ఈ గురువు ఎవరి కుమారుడో ఉపనిషత్తు చెప్పదు. సంప్రదాయం ఆయనను దధీచి కుమారునితో కలుపుతుంది; ఒకే పేరున్న వేర్వేరు వ్యక్తులు కావచ్చని కొందరు ఆధునిక పాఠకులు భావిస్తారు. గ్రంథాలు చెప్పినట్టే మనం రెండూ చెబుతున్నాం; రెండింటినీ కలిపి మనసులో ఉంచుకోండి."]
  ],
  [
   ["h", "Six who came with firewood", "సమిధలతో వచ్చిన ఆరుగురు"],
   ["p", "Six seekers came together: {sukesha|Sukeśā Bhāradvāja}; {satyakama_s|Śaibya Satyakāma}, son of Śibi; {sauryayani|Sauryāyaṇī Gārgya}; {kausalya_a|Kausalya Āśvalāyana}; {bhargava_v|Bhārgava Vaidarbhi}; and {kabandhi|Kabandhī Kātyāyana}. The Upaniṣad says they were already devoted to Brahman, already grounded in it, and were now searching for the highest Brahman. They thought, “This man will tell us all of it,” and came to the revered Pippalāda with firewood in their hands.", "ఆరుగురు సాధకులు కలిసి వచ్చారు: {sukesha|సుకేశ భారద్వాజుడు}; శిబి కుమారుడు {satyakama_s|శైబ్య సత్యకాముడు}; {sauryayani|సౌర్యాయణి గార్గ్యుడు}; {kausalya_a|కౌసల్య ఆశ్వలాయనుడు}; {bhargava_v|భార్గవ వైదర్భి}; {kabandhi|కబంధి కాత్యాయనుడు}. వాళ్ళు అప్పటికే బ్రహ్మ నిష్ఠ కలవారనీ, బ్రహ్మపరులనీ, ఇప్పుడు పరబ్రహ్మను వెతుకుతున్నారనీ ఉపనిషత్తు చెబుతుంది. “ఈయన మనకు అంతా చెబుతాడు” అనుకుని, చేతిలో సమిధలతో పూజ్యుడైన పిప్పలాదుని దగ్గరకు వచ్చారు."],
   ["dyk", "🪵", "Coming “with firewood in hand” (samit-pāṇi) was the old sign of a student asking to be taught. The firewood was for the teacher's sacred fire — a small, humble gift that said, “I am ready to serve and to learn.”", "‘చేతిలో సమిధలతో’ (సమిత్పాణి) రావడం — బోధించమని అడిగే శిష్యుని ప్రాచీన గుర్తు. ఆ సమిధలు గురువు యజ్ఞాగ్ని కోసం — “సేవ చేయడానికీ, నేర్చుకోవడానికీ సిద్ధంగా ఉన్నాను” అని చెప్పే చిన్న, వినయపూర్వకమైన కానుక."]
  ],
  [
   ["h", "“Stay one more year”", "“ఇంకో ఏడాది ఉండండి”"],
   ["p", "Pippalāda did not answer them at once. He said:", "పిప్పలాదుడు వెంటనే జవాబివ్వలేదు. ఆయన అన్నాడు:"],
   ["sloka", ["భూయ ఏవ తపసా బ్రహ్మచర్యేణ శ్రద్ధయా సంవత్సరం సంవత్స్యథ ।", "యథాకామం ప్రశ్నాన్ పృచ్ఛత యది విజ్ఞాస్యామః సర్వం హ వో వక్ష్యామ ఇతి ॥"], ["bhūya eva tapasā brahmacaryeṇa śraddhayā saṃvatsaraṃ saṃvatsyatha |", "yathākāmaṃ praśnān pṛcchata yadi vijñāsyāmaḥ sarvaṃ ha vo vakṣyāma iti ||"], "“Live here one more year, with tapas, with self-discipline, with faith. Then ask whatever questions you wish. If we know, we will tell you all of it.” (Praśna Upaniṣad 1.2)", "“తపస్సుతో, బ్రహ్మచర్యంతో, శ్రద్ధతో ఇంకో సంవత్సరం ఇక్కడ ఉండండి. తర్వాత మీకు ఇష్టమైన ప్రశ్నలు అడగండి. మాకు తెలిస్తే అంతా మీకు చెబుతాం.” (ప్రశ్నోపనిషత్తు 1.2)"],
   ["p", "Notice two things. First, the year: these were not beginners, yet he asked them to wait, to work and to quiet themselves before the answers. Second, that little word “if” — “if we know.” The great teacher does not promise to know everything. {shankara|Śaṅkara}, in his commentary, says this “if” shows the teacher's freedom from pride, not any doubt in his knowledge.", "రెండు విషయాలు గమనించండి. మొదటిది — ఏడాది: వీళ్ళు కొత్తవాళ్ళు కారు; అయినా జవాబులకు ముందు వేచి ఉండమనీ, శ్రమించమనీ, మనసు నిశ్చలం చేసుకోమనీ అడిగాడు. రెండవది — ఆ చిన్న మాట ‘తెలిస్తే’. ఆ మహా గురువు తనకు అంతా తెలుసని వాగ్దానం చేయడు. ఈ ‘తెలిస్తే’ గురువు జ్ఞానంలోని సందేహాన్ని కాదు, ఆయన నిరహంకారాన్ని చూపుతుందని {shankara|శంకరాచార్యులు} తమ భాష్యంలో అంటారు."]
  ],
  [
   ["h", "The prayer before the questions", "ప్రశ్నలకు ముందు ప్రార్థన"],
   ["p", "The Praśna Upaniṣad is chanted with a peace prayer it shares with the other Atharvaveda Upaniṣads. Telugu students still learn it by heart:", "ప్రశ్నోపనిషత్తును ఇతర అథర్వవేద ఉపనిషత్తులతో పంచుకునే శాంతి మంత్రంతో పఠిస్తారు. తెలుగు విద్యార్థులు ఇప్పటికీ దీన్ని కంఠస్థం చేస్తారు:"],
   ["sloka", ["భద్రం కర్ణేభిః శృణుయామ దేవాః । భద్రం పశ్యేమాక్షభిర్యజత్రాః ।", "స్థిరైరంగైస్తుష్టువాంసస్తనూభిః । వ్యశేమ దేవహితం యదాయుః ॥"], ["bhadraṃ karṇebhiḥ śṛṇuyāma devāḥ | bhadraṃ paśyemākṣabhir yajatrāḥ |", "sthirair aṅgais tuṣṭuvāṃsas tanūbhiḥ | vyaśema devahitaṃ yad āyuḥ ||"], "“O gods, may we hear what is good with our ears. O holy ones, may we see what is good with our eyes. With steady limbs and bodies, praising you, may we live out the life the gods have given us.”", "“ఓ దేవతలారా, మా చెవులతో మంచినే విందాం. పూజ్యులారా, మా కళ్ళతో మంచినే చూద్దాం. దృఢమైన అవయవాలతో, శరీరాలతో మిమ్మల్ని స్తుతిస్తూ, దేవతలు మాకిచ్చిన ఆయుష్షును పూర్తిగా జీవిద్దాం.”"],
   ["src", "Praśna Upaniṣad 1.1–2 (the six seekers, firewood in hand; Pippalāda's command to stay a year) and Śaṅkara's commentary. The peace prayer “bhadraṃ karṇebhiḥ” is from the Ṛgveda (1.89.8) and is chanted with the Atharvaveda Upaniṣads.", "ప్రశ్నోపనిషత్తు 1.1–2 (సమిధలతో వచ్చిన ఆరుగురు; ఏడాది ఉండమన్న పిప్పలాదుని ఆజ్ఞ), శంకర భాష్యం. ‘భద్రం కర్ణేభిః’ శాంతి మంత్రం ఋగ్వేదం (1.89.8) నుండి; అథర్వవేద ఉపనిషత్తులతో పఠిస్తారు."]
  ]
 ],
 remember: [
  ["The Praśna Upaniṣad of the Atharvaveda is built around {pippalada|Pippalāda} and six seekers.", "అథర్వవేదంలోని ప్రశ్నోపనిషత్తు {pippalada|పిప్పలాదుడు}, ఆరుగురు సాధకుల చుట్టూ అల్లబడింది."],
  ["They came with firewood in hand — the sign of a humble student.", "వాళ్ళు చేతిలో సమిధలతో వచ్చారు — వినయం గల శిష్యుని గుర్తు."],
  ["He made them wait a year in tapas and faith, and promised to answer “if we know.”", "తపస్సు, శ్రద్ధలతో ఏడాది వేచి ఉండమని, ‘మాకు తెలిస్తే’ జవాబిస్తానని చెప్పాడు."]
 ],
 think: ["Pippalāda said, “If we know, we will tell you.” Why might a great teacher be willing to say he might not know?", "“మాకు తెలిస్తే చెబుతాం” అన్నాడు పిప్పలాదుడు. గొప్ప గురువు ‘నాకు తెలియకపోవచ్చు’ అనడానికి ఎందుకు సిద్ధంగా ఉంటాడు?"]
},
{
 id: "ppl-6", sage: "pippalada", n: 6, order: 4606, date: "2026-11-19",
 title: "Where Do Creatures Come From?", titleTe: "ప్రాణులు ఎక్కడి నుండి వస్తాయి?",
 src: "Praśna Upaniṣad 1",
 who: ["pippalada", "kabandhi", "prajapati"],
 pages: [
  [
   ["p", "When the year was over, {kabandhi|Kabandhī Kātyāyana} came first and asked: “Revered sir, from where are all these creatures born?”", "ఏడాది పూర్తయ్యాక {kabandhi|కబంధి కాత్యాయనుడు} ముందుకు వచ్చి అడిగాడు: “పూజ్యులారా, ఈ ప్రాణులన్నీ ఎక్కడి నుండి పుడుతున్నాయి?”"],
   ["p", "{pippalada|Pippalāda} answered with a story of the beginning. {prajapati|Prajāpati}, the Lord of creatures, wished for offspring. He did tapas, and from that tapas he brought forth a pair: rayi and prāṇa — “matter” and “life”. He thought, “These two together will make creatures for me in many ways.”", "{pippalada|పిప్పలాదుడు} ఆది కథతో జవాబిచ్చాడు. ప్రాణులకు ప్రభువైన {prajapati|ప్రజాపతి} సంతానం కోరుకున్నాడు. తపస్సు చేశాడు; ఆ తపస్సు నుండి ఒక జంటను పుట్టించాడు: రయి, ప్రాణం — ‘పదార్థం’, ‘జీవం’. “ఈ రెండూ కలిసి నాకు ఎన్నో విధాలుగా ప్రాణులను పుట్టిస్తాయి” అనుకున్నాడు."]
  ],
  [
   ["h", "Sun and Moon", "సూర్యుడు, చంద్రుడు"],
   ["p", "The Sun, said Pippalāda, is life; the Moon is matter. Indeed everything that has form — and everything without form too — is matter, rayi. When the Sun rises and spreads its light east, west, north, south, above and below, it gathers up the life of all those directions into its rays. The Sun is the fire of every form, the life of the whole world, rising each morning.", "సూర్యుడు జీవం, చంద్రుడు పదార్థం అన్నాడు పిప్పలాదుడు. నిజానికి రూపం ఉన్నదంతా — రూపం లేనిది కూడా — పదార్థమే, రయే. సూర్యుడు ఉదయించి తూర్పు, పడమర, ఉత్తరం, దక్షిణం, పైన, కింద — అన్ని దిక్కులకూ వెలుగు పంచినప్పుడు, ఆ దిక్కులన్నిటి జీవాన్ని తన కిరణాల్లో నింపుకుంటాడు. ప్రతి రూపంలోని అగ్ని సూర్యుడే; ప్రతి ఉదయం ఉదయించే లోకమంతటి ప్రాణం ఆయనే."],
   ["p", "Then he showed the same pair everywhere in time. The year is Prajāpati, and it has two paths, a southern and a northern. The month is Prajāpati: its dark half is matter, its bright half is life. Day and night are Prajāpati: the day is life, the night is matter. And food is Prajāpati — from food comes seed, and from seed come creatures.", "తర్వాత అదే జంటను కాలంలో అంతటా చూపించాడు. సంవత్సరం ప్రజాపతి; దానికి దక్షిణాయనం, ఉత్తరాయణం అనే రెండు మార్గాలు. నెల ప్రజాపతి: కృష్ణపక్షం పదార్థం, శుక్లపక్షం జీవం. పగలూ రాత్రీ ప్రజాపతి: పగలు జీవం, రాత్రి పదార్థం. అన్నం ప్రజాపతి — అన్నం నుండి బీజం, బీజం నుండి ప్రాణులు."]
  ],
  [
   ["h", "Two roads after death", "మరణం తర్వాత రెండు దారులు"],
   ["p", "Those who give themselves only to rituals and to good works — sacrifices, wells, rest-houses — win the world of the Moon, the southern path, the path of the ancestors; and from there they return again to birth. But those who seek the Self through tapas, self-discipline, faith and knowledge go by the northern path to the Sun. That, said Pippalāda, is the home of all life, the immortal, the fearless, the highest goal. From there they do not return.", "యజ్ఞాలు, బావులు, సత్రాలు వంటి కర్మలకూ సత్కార్యాలకూ మాత్రమే అంకితమైనవారు చంద్రలోకాన్ని — దక్షిణ మార్గాన్ని, పితృయానాన్ని — పొందుతారు; అక్కడి నుండి మళ్ళీ జన్మకు తిరిగి వస్తారు. కానీ తపస్సు, బ్రహ్మచర్యం, శ్రద్ధ, జ్ఞానంతో ఆత్మను వెతికేవారు ఉత్తర మార్గంలో సూర్యుని చేరతారు. అదే సర్వ ప్రాణాలకూ నెలవు, అమృతం, భయం లేనిది, పరమ గమ్యం అన్నాడు పిప్పలాదుడు. అక్కడి నుండి వాళ్ళు తిరిగి రారు."],
   ["p", "He ended the first answer with a line that every student of the Upaniṣads remembers: the pure world of Brahman belongs to those in whom there is no crookedness, no falsehood and no deceit.", "ఉపనిషత్తులు చదివే ప్రతి విద్యార్థీ గుర్తుంచుకునే మాటతో మొదటి జవాబు ముగించాడు: ఎవరిలో వంకరతనం, అబద్ధం, మోసం ఉండవో — నిర్మలమైన బ్రహ్మలోకం వారిదే."],
   ["dyk", "🌗", "Telugu calendars still divide every month into శుక్లపక్షం and కృష్ణపక్షం, and the year into ఉత్తరాయణం and దక్షిణాయనం — Sankranti marks the turn to the northern path. Pippalāda uses these very divisions to teach.", "తెలుగు పంచాంగాలు ఇప్పటికీ ప్రతి నెలనూ శుక్లపక్షం, కృష్ణపక్షంగా, సంవత్సరాన్ని ఉత్తరాయణం, దక్షిణాయనంగా విభజిస్తాయి — ఉత్తరాయణ ప్రారంభమే సంక్రాంతి. పిప్పలాదుడు బోధించడానికి ఇవే విభాగాలను వాడాడు."],
   ["src", "Praśna Upaniṣad, first question (Kabandhī Kātyāyana: Prajāpati's tapas; rayi and prāṇa; Sun and Moon; the year, month, day and night, and food as Prajāpati; the southern and northern paths; the world of Brahman for those without crookedness, falsehood or deceit).", "ప్రశ్నోపనిషత్తు, మొదటి ప్రశ్న (కబంధి కాత్యాయనుడు: ప్రజాపతి తపస్సు; రయి, ప్రాణం; సూర్యచంద్రులు; సంవత్సరం, నెల, పగలు-రాత్రి, అన్నం ప్రజాపతిగా; దక్షిణ, ఉత్తర మార్గాలు; వంకరతనం, అబద్ధం, మోసం లేనివారికి బ్రహ్మలోకం)."]
  ]
 ],
 remember: [
  ["{kabandhi|Kabandhī} asked where creatures come from.", "ప్రాణులు ఎక్కడి నుండి వస్తాయని {kabandhi|కబంధి} అడిగాడు."],
  ["{pippalada|Pippalāda} said {prajapati|Prajāpati} made a pair, matter and life, and saw that pair in sun and moon, day and night.", "{prajapati|ప్రజాపతి} పదార్థం, జీవం అనే జంటను సృష్టించాడనీ, సూర్యచంద్రుల్లో, పగలు-రాత్రుల్లో ఆ జంటే ఉందనీ {pippalada|పిప్పలాదుడు} చెప్పాడు."],
  ["The highest world belongs to those without crookedness, falsehood or deceit.", "వంకరతనం, అబద్ధం, మోసం లేనివారిదే పరమ లోకం."]
 ],
 think: ["Pippalāda saw “matter and life” as a pair in everything — sun and moon, day and night. Can you find such a pair in your own day?", "పిప్పలాదుడు ప్రతిదానిలో ‘పదార్థం, జీవం’ అనే జంటను చూశాడు — సూర్యచంద్రులు, పగలు-రాత్రి. మీ రోజులో అలాంటి జంటను మీరు కనుగొనగలరా?"]
},
{
 id: "ppl-7", sage: "pippalada", n: 7, order: 4607, date: "2026-11-19",
 title: "Breath, the King of the Body", titleTe: "ప్రాణం — శరీరానికి రాజు",
 src: "Praśna Upaniṣad 2–3",
 who: ["pippalada", "bhargava_v", "kausalya_a"],
 pages: [
  [
   ["p", "Next, {bhargava_v|Bhārgava Vaidarbhi} asked: “Sir, how many powers hold up a living being? Which of them light it up? And which is the greatest?”", "తర్వాత {bhargava_v|భార్గవ వైదర్భి} అడిగాడు: “స్వామీ, ఒక ప్రాణిని ఎన్ని శక్తులు నిలుపుతాయి? వాటిలో ఏవి దాన్ని ప్రకాశింపజేస్తాయి? వాటిలో గొప్పది ఏది?”"],
   ["p", "{pippalada|Pippalāda} told a story. Space, wind, fire, water and earth, and speech, mind, sight and hearing — all these powers once boasted: “We hold up this body; we keep it together.” Then Breath, prāṇa, the chief of them, said, “Do not fool yourselves. It is I who, dividing myself five ways, hold up this body.” They did not believe him.", "{pippalada|పిప్పలాదుడు} ఒక కథ చెప్పాడు. ఆకాశం, వాయువు, అగ్ని, నీరు, భూమి; మాట, మనసు, చూపు, వినికిడి — ఈ శక్తులన్నీ ఒకప్పుడు గొప్పలు చెప్పుకున్నాయి: “ఈ శరీరాన్ని మేమే నిలుపుతున్నాం; మేమే కలిపి ఉంచుతున్నాం.” అప్పుడు వాటిలో ముఖ్యమైన ప్రాణం అంది: “మిమ్మల్ని మీరు మోసం చేసుకోకండి. నన్ను నేను ఐదుగా విభజించుకుని ఈ శరీరాన్ని నిలుపుతున్నది నేనే.” అవి నమ్మలేదు."]
  ],
  [
   ["h", "The bees and their king", "తేనెటీగలు, వాటి రాజు"],
   ["p", "So Breath, in pride, began to rise up and leave the body. And as he rose, all the others were forced to rise with him; when he settled back, they all settled. It was, said Pippalāda, just like bees: when the king of the bees flies up, all the bees fly up; when he settles, they all settle. Speech, mind, eye and ear saw it — and now they praised Breath.", "అప్పుడు ప్రాణం గర్వంతో శరీరం నుండి పైకి లేచి వెళ్ళిపోవడం మొదలుపెట్టింది. అది లేవగానే మిగతావన్నీ దానితో పాటు లేవక తప్పలేదు; అది తిరిగి కూర్చోగానే అన్నీ కూర్చున్నాయి. అది అచ్చం తేనెటీగల లాగే అన్నాడు పిప్పలాదుడు: తేనెటీగల రాజు పైకి ఎగిరితే ఈగలన్నీ ఎగురుతాయి; అది వాలితే అన్నీ వాలతాయి. మాట, మనసు, కన్ను, చెవి అది చూశాయి — ఇప్పుడు ప్రాణాన్ని కీర్తించాయి."],
   ["p", "“You burn as fire, you shine as the sun, you rain as the cloud, you are Indra and the wind, you are the earth and the moon, what is and what is not, and what never dies. As spokes are fixed in the hub of a wheel, everything is fixed in you. Protect us as a mother protects her children.”", "“అగ్నిగా నువ్వే మండుతావు, సూర్యునిగా ప్రకాశిస్తావు, మేఘంగా వర్షిస్తావు; ఇంద్రుడివీ వాయువువీ నువ్వే; భూమివీ చంద్రుడివీ, ఉన్నదీ లేనిదీ, ఎన్నటికీ చావనిదీ నువ్వే. చక్రం నాభిలో ఆకులు ఇమిడినట్టు అన్నీ నీలోనే ఇమిడి ఉన్నాయి. తల్లి బిడ్డలను కాపాడినట్టు మమ్మల్ని కాపాడు.”"],
   ["dyk", "🐝", "The Upaniṣad says “king of the bees” (madhukara-rāja). Ancient people everywhere thought the leader of the hive was a king; today we know it is a queen. The lesson is the same: when the one at the centre goes, everyone goes.", "ఉపనిషత్తు ‘తేనెటీగల రాజు’ (మధుకరరాజు) అంటుంది. ప్రాచీన కాలంలో అన్ని దేశాల్లో తేనెపట్టు నాయకుడు రాజు అనుకునేవారు; ఇప్పుడు అది రాణి అని మనకు తెలుసు. పాఠం మాత్రం అదే: మధ్యలో ఉన్నది వెళ్ళిపోతే అందరూ వెళ్ళిపోతారు."]
  ],
  [
   ["h", "“You ask beyond the limit”", "“హద్దు దాటి అడుగుతున్నావు”"],
   ["p", "Then {kausalya_a|Kausalya Āśvalāyana} pushed further: “Where is this Breath born from? How does it come into the body? How does it divide itself and stay there? How does it leave? How does it hold up what is outside and what is within?”", "అప్పుడు {kausalya_a|కౌసల్య ఆశ్వలాయనుడు} ఇంకా ముందుకు వెళ్ళాడు: “ఈ ప్రాణం ఎక్కడి నుండి పుడుతుంది? శరీరంలోకి ఎలా వస్తుంది? తనను తాను ఎలా విభజించుకుని అక్కడ ఉంటుంది? ఎలా వెళ్ళిపోతుంది? బయట ఉన్నదాన్నీ, లోపల ఉన్నదాన్నీ ఎలా నిలుపుతుంది?”"],
   ["p", "Pippalāda smiled at that. “You ask questions beyond the limit,” he said. “But you are deeply devoted to Brahman, so I will answer.” Breath is born from the Self, as a shadow falls from a person. It enters the body through the working of the mind.", "దానికి పిప్పలాదుడు నవ్వాడు. “హద్దు దాటిన ప్రశ్నలు అడుగుతున్నావు,” అన్నాడు. “కానీ నువ్వు బ్రహ్మను ఎంతో నిష్ఠతో ఆశ్రయించావు, అందుకే చెబుతాను.” మనిషి నుండి నీడ పడినట్టు ప్రాణం ఆత్మ నుండి పుడుతుంది. మనసు చేసే పనుల వల్ల శరీరంలోకి వస్తుంది."]
  ],
  [
   ["h", "A king and his officers", "రాజు, అతని అధికారులు"],
   ["p", "Just as a king appoints his officers — “You govern these villages, you govern those” — so Breath sets the other breaths each in its place. Apāna works in the lower body, in letting go and in giving birth. Prāṇa itself lives in the eyes, ears, mouth and nose. Samāna, in the middle, spreads the food that is offered into the body evenly to every part. In the heart lives the Self; from it run a hundred and one channels, each with a hundred branches, each of those with seventy-two thousand more — and through them all moves vyāna. And udāna, rising through one channel, leads a person at death upward to a good world by good deeds, to a bad one by bad deeds, and back to the human world by both.", "రాజు తన అధికారులను — “నువ్వు ఈ గ్రామాలు పాలించు, నువ్వు ఆ గ్రామాలు పాలించు” అని నియమించినట్టు, ప్రాణం మిగతా ప్రాణాలను వాటి వాటి స్థానాల్లో నిలుపుతుంది. అపానం శరీరం కింది భాగంలో — విసర్జనలో, ప్రసవంలో — పనిచేస్తుంది. ప్రాణం స్వయంగా కళ్ళు, చెవులు, నోరు, ముక్కుల్లో ఉంటుంది. మధ్యలో ఉండే సమానం, శరీరంలోకి అర్పించిన అన్నాన్ని ప్రతి భాగానికీ సమానంగా పంచుతుంది. హృదయంలో ఆత్మ ఉంటుంది; అక్కడి నుండి నూట ఒక్క నాడులు; ప్రతిదానికీ వంద శాఖలు; ప్రతి శాఖకూ డెబ్బై రెండు వేల ఉపనాడులు — వాటన్నిటిలో వ్యానం సంచరిస్తుంది. ఉదానం ఒక నాడి ద్వారా పైకి లేచి, మరణ సమయంలో మనిషిని — పుణ్యంతో మంచి లోకానికి, పాపంతో చెడ్డ లోకానికి, రెండింటితో మళ్ళీ మనుషుల లోకానికి — తీసుకెళ్తుంది."],
   ["p", "Outside, too, the same powers work: the Sun is the outer prāṇa, the earth's power holds the apāna, the space between is samāna, the air is vyāna, and fire's heat is udāna. One who knows Breath this way, said Pippalāda, gains immortality.", "బయట కూడా ఇవే శక్తులు పనిచేస్తాయి: సూర్యుడు బాహ్య ప్రాణం; భూమి శక్తి అపానాన్ని నిలుపుతుంది; మధ్యలోని ఆకాశం సమానం; గాలి వ్యానం; అగ్ని వేడి ఉదానం. ప్రాణాన్ని ఇలా తెలుసుకున్నవాడు అమృతత్వాన్ని పొందుతాడని పిప్పలాదుడు అన్నాడు."],
   ["src", "Praśna Upaniṣad, second question (Bhārgava Vaidarbhi: the powers' quarrel, Breath rising and the bees, the praise of Breath) and third question (Kausalya Āśvalāyana: Breath born of the Self like a shadow; the five breaths as a king's officers; the channels of the heart; udāna at death; the outer powers).", "ప్రశ్నోపనిషత్తు, రెండవ ప్రశ్న (భార్గవ వైదర్భి: శక్తుల వాదం, ప్రాణం లేవడం, తేనెటీగలు, ప్రాణ స్తుతి), మూడవ ప్రశ్న (కౌసల్య ఆశ్వలాయనుడు: నీడ లాగా ఆత్మ నుండి ప్రాణం; రాజు అధికారుల లాగా ఐదు ప్రాణాలు; హృదయ నాడులు; మరణ సమయంలో ఉదానం; బాహ్య శక్తులు)."]
  ]
 ],
 remember: [
  ["The senses boasted, but when Breath rose to leave, they all had to go — like bees with their leader.", "ఇంద్రియాలు గొప్పలు చెప్పుకున్నాయి; ప్రాణం వెళ్ళబోగానే — నాయకుని వెంట ఈగల్లా — అన్నీ వెళ్ళక తప్పలేదు."],
  ["Breath is born from the Self, as a shadow from a person.", "మనిషి నుండి నీడ లాగా ప్రాణం ఆత్మ నుండి పుడుతుంది."],
  ["Like a king's officers, the five breaths each have their own work.", "రాజు అధికారుల లాగా ఐదు ప్రాణాలకూ ఒక్కొక్క పని ఉంది."]
 ],
 think: ["The senses each thought they were the most important. In a family or a team, how can we tell what truly holds everything together?", "ప్రతి ఇంద్రియం తానే ముఖ్యమని అనుకుంది. ఒక కుటుంబంలో లేదా జట్టులో అన్నిటినీ నిజంగా కలిపి ఉంచేదేదో మనం ఎలా తెలుసుకోవచ్చు?"]
},
{
 id: "ppl-8", sage: "pippalada", n: 8, order: 4608, date: "2026-11-19",
 title: "What Sleeps, What Wakes — and the Syllable Om", titleTe: "ఏది నిద్రిస్తుంది, ఏది మేల్కొంటుంది — ఓంకారం",
 src: "Praśna Upaniṣad 4–5",
 who: ["pippalada", "sauryayani", "satyakama_s", "garga"],
 pages: [
  [
   ["p", "The fourth seeker, {sauryayani|Sauryāyaṇī Gārgya} of Garga's family, asked about the night: “In a person, what is it that sleeps? What stays awake? Which god sees the dreams? Whose is the happiness of deep sleep? In whom are all these established?”", "నాలుగవ సాధకుడు, గర్గ వంశపు {sauryayani|సౌర్యాయణి గార్గ్యుడు} రాత్రి గురించి అడిగాడు: “మనిషిలో నిద్రపోయేది ఏది? మేలుకొని ఉండేది ఏది? కలలు చూసే దేవత ఎవరు? గాఢనిద్ర సుఖం ఎవరిది? ఇవన్నీ ఎవరిలో నిలిచి ఉన్నాయి?”"],
   ["p", "{pippalada|Pippalāda} said: when the sun sets, all its rays are drawn back into its disc of light, and when it rises they spread out again. In the same way, in sleep all the senses are drawn into the mind, the highest of them. Then the person does not hear, see, smell, taste, touch, speak, take or move. “He is sleeping,” people say.", "{pippalada|పిప్పలాదుడు} అన్నాడు: సూర్యుడు అస్తమించినప్పుడు అతని కిరణాలన్నీ తిరిగి ఆ వెలుగు బింబంలోకి చేరతాయి; ఉదయించగానే మళ్ళీ విస్తరిస్తాయి. అలాగే నిద్రలో ఇంద్రియాలన్నీ వాటిలో గొప్పదైన మనసులోకి చేరతాయి. అప్పుడు మనిషి వినడు, చూడడు, వాసన చూడడు, రుచి చూడడు, తాకడు, మాట్లాడడు, పట్టుకోడు, కదలడు. “నిద్రపోతున్నాడు” అంటారు జనం."]
  ],
  [
   ["h", "The fires that keep watch", "కాపలా కాసే అగ్నులు"],
   ["p", "But the breaths stay awake, like sacred fires kept burning all night in the “city” of the body. Pippalāda compared them to the fires of a household sacrifice: the out-going and in-going breaths are offerings, samāna balances them, the mind is the one who sacrifices, and udāna is the fruit, leading the sacrificer each night close to Brahman.", "కానీ ప్రాణాలు మేలుకొని ఉంటాయి — శరీరమనే ‘పురం’లో రాత్రంతా వెలిగే పవిత్రాగ్నుల లాగా. పిప్పలాదుడు వాటిని గృహ యజ్ఞపు అగ్నులతో పోల్చాడు: బయటకు, లోపలికి వెళ్ళే శ్వాసలు ఆహుతులు; సమానం వాటిని సమం చేస్తుంది; మనసు యజమాని; ఉదానం ఆ యజ్ఞ ఫలం — ప్రతి రాత్రీ యజమానిని బ్రహ్మకు దగ్గరగా తీసుకెళ్తుంది."],
   ["p", "In dreams, the mind — the “god” within — enjoys its own greatness: it sees again what it has seen and hears again what it has heard; it sees what was seen and unseen, heard and unheard, real and unreal. But when it is overpowered by the inner light, it sees no dreams, and then a great happiness arises in the body.", "కలల్లో మనసు — లోపలి ‘దేవుడు’ — తన మహిమను అనుభవిస్తుంది: చూసిందాన్ని మళ్ళీ చూస్తుంది, విన్నదాన్ని మళ్ళీ వింటుంది; చూసినదీ చూడనిదీ, విన్నదీ వినలేనిదీ, ఉన్నదీ లేనిదీ చూస్తుంది. కానీ లోపలి వెలుగు దాన్ని ఆవరించినప్పుడు కలలు చూడదు; అప్పుడు శరీరంలో గొప్ప సుఖం పుడుతుంది."]
  ],
  [
   ["h", "Birds coming home", "గూటికి చేరే పక్షులు"],
   ["p", "“As birds go to the tree where they live, dear one, so all of this goes to the highest Self”: earth and its subtle element, water and its element, fire, air and space; the eye and what is seen, the ear and what is heard, the mind and what is thought — all rest in the imperishable Self. Whoever knows that shadowless, bodiless, colourless, pure, imperishable one becomes the imperishable, knows all, becomes all.", "“నాయనా, పక్షులు తాము నివసించే చెట్టుకు చేరినట్టు, ఇదంతా పరమాత్మను చేరుతుంది”: భూమీ దాని సూక్ష్మ తత్త్వమూ, నీరూ దాని తత్త్వమూ, అగ్ని, వాయువు, ఆకాశం; కన్నూ చూడబడేదీ, చెవీ వినబడేదీ, మనసూ ఆలోచించబడేదీ — అన్నీ నాశనం లేని ఆత్మలో విశ్రమిస్తాయి. నీడ లేని, శరీరం లేని, రంగు లేని, నిర్మలమైన, నాశనం లేని ఆ తత్త్వాన్ని తెలుసుకున్నవాడు అక్షరుడవుతాడు, సర్వజ్ఞుడవుతాడు, సర్వమూ అవుతాడు."],
   ["sglink", "Sauryāyaṇī and the Gārgya family", "సౌర్యాయణి, గార్గ్య వంశం", "gg-9"]
  ],
  [
   ["h", "Om until the last breath", "చివరి శ్వాస వరకు ఓం"],
   ["p", "Then {satyakama_s|Śaibya Satyakāma} asked: “If someone meditates on Om all through life until death, what world does he win?”", "అప్పుడు {satyakama_s|శైబ్య సత్యకాముడు} అడిగాడు: “జీవితమంతా, మరణం వరకు ఎవరైనా ఓంకారాన్ని ధ్యానిస్తే అతను ఏ లోకాన్ని పొందుతాడు?”"],
   ["p", "Pippalāda answered that Om is both the higher and the lower Brahman. One who meditates on it as one measure comes quickly back to this earth, led by the verses of the Ṛgveda, and lives a great human life of tapas and faith. One who meditates on it as two measures rises to the world of the Moon, led by the Yajurveda, enjoys it, and returns. But one who meditates on the highest Person through the full syllable of three measures becomes one with the light of the Sun. As a snake slips out of its old skin, he slips free of all wrongdoing; the chants of the Sāmaveda lead him up to the world of Brahman, and there he sees the Person higher than the highest, who lives in the city of the body.", "ఓం పర బ్రహ్మా, అపర బ్రహ్మా రెండూ అని పిప్పలాదుడు జవాబిచ్చాడు. దాన్ని ఒక మాత్రగా ధ్యానించేవాడు ఋగ్వేద మంత్రాల నడిపింపుతో త్వరగా ఈ భూమికి తిరిగి వచ్చి, తపస్సు, శ్రద్ధలతో గొప్ప మానవ జీవితం గడుపుతాడు. రెండు మాత్రలుగా ధ్యానించేవాడు యజుర్వేదం నడిపింపుతో చంద్రలోకానికి వెళ్ళి, అక్కడ సుఖించి, తిరిగి వస్తాడు. కానీ మూడు మాత్రల పూర్తి ఓంకారంతో పరమ పురుషుణ్ణి ధ్యానించేవాడు సూర్యుని తేజస్సుతో ఒక్కటవుతాడు. పాము పాత కుబుసం విడిచినట్టు పాపాలన్నిటి నుండి విడివడతాడు; సామవేద గానాలు అతన్ని బ్రహ్మలోకానికి తీసుకెళ్తాయి; అక్కడ శరీరమనే పురంలో నివసించే, పరాత్పరుడైన పురుషుణ్ణి దర్శిస్తాడు."],
   ["dyk", "🕉️", "The three measures of Om are A, U and M. The Māṇḍūkya Upaniṣad — also of the Atharvaveda — teaches them as waking, dreaming and deep sleep, with a silent fourth beyond them. Pippalāda's two answers, on sleep and on Om, sit side by side for a reason.", "ఓంకారంలోని మూడు మాత్రలు — అ, ఉ, మ. అథర్వవేదానికే చెందిన మాండూక్య ఉపనిషత్తు వాటిని జాగ్రత్, స్వప్న, సుషుప్తి అవస్థలుగా, వాటిని దాటిన నిశ్శబ్ద ‘తురీయం’తో బోధిస్తుంది. నిద్ర గురించీ, ఓం గురించీ పిప్పలాదుడిచ్చిన రెండు జవాబులు పక్కపక్కనే ఉండడానికి కారణం ఉంది."],
   ["src", "Praśna Upaniṣad, fourth question (Sauryāyaṇī Gārgya: the sun's rays and the mind; the breaths as sacred fires; dreams; deep sleep; birds returning to the tree) and fifth question (Śaibya Satyakāma: Om as higher and lower Brahman; one, two and three measures; the snake and its skin). Compare the Māṇḍūkya Upaniṣad on A-U-M.", "ప్రశ్నోపనిషత్తు, నాలుగవ ప్రశ్న (సౌర్యాయణి గార్గ్యుడు: సూర్య కిరణాలు, మనసు; పవిత్రాగ్నుల లాంటి ప్రాణాలు; కలలు; గాఢనిద్ర; చెట్టుకు చేరే పక్షులు), ఐదవ ప్రశ్న (శైబ్య సత్యకాముడు: పర, అపర బ్రహ్మగా ఓం; ఒకటి, రెండు, మూడు మాత్రలు; పాము కుబుసం). అ-ఉ-మ గురించి మాండూక్య ఉపనిషత్తు కూడా చూడండి."]
  ]
 ],
 remember: [
  ["In sleep the senses gather into the mind as the sun's rays gather at sunset.", "సాయంకాలం సూర్య కిరణాలు బింబంలో చేరినట్టు నిద్రలో ఇంద్రియాలు మనసులో చేరతాయి."],
  ["In deep sleep all things rest in the Self, like birds returning to their tree.", "గాఢనిద్రలో — చెట్టుకు తిరిగి వచ్చే పక్షుల్లా — అన్నీ ఆత్మలో విశ్రమిస్తాయి."],
  ["Meditating on full Om frees one as a snake slips out of its old skin.", "పూర్తి ఓంకార ధ్యానం — పాము కుబుసం విడిచినట్టు — మనిషిని విముక్తుణ్ణి చేస్తుంది."]
 ],
 think: ["Every night we go into deep sleep and come back. Pippalāda says we rest in the Self there. What do you think “rests” in you when you sleep well?", "ప్రతి రాత్రీ మనం గాఢనిద్రలోకి వెళ్ళి తిరిగి వస్తాం. అక్కడ మనం ఆత్మలో విశ్రమిస్తామని పిప్పలాదుడు అంటాడు. మీరు బాగా నిద్రపోయినప్పుడు మీలో ఏది ‘విశ్రమిస్తుంది’ అనుకుంటున్నారు?"]
},
{
 id: "ppl-9", sage: "pippalada", n: 9, order: 4609, date: "2026-11-19",
 title: "The Person of Sixteen Parts", titleTe: "పదహారు కళల పురుషుడు",
 src: "Praśna Upaniṣad 6",
 who: ["pippalada", "sukesha", "hiranyanabha"],
 pages: [
  [
   ["p", "The last to ask was {sukesha|Sukeśā Bhāradvāja}, and he began with a confession. “Sir, {hiranyanabha|Hiraṇyanābha}, a prince of Kosala, once came to me and asked: ‘Bhāradvāja, do you know the Person of sixteen parts?’ I said to the young man, ‘I do not know him. If I knew him, how could I not tell you? Whoever speaks untruth dries up to the very root. So I will not speak untruth.’ The prince climbed into his chariot in silence and drove away. Now I ask you: where is that Person?”", "చివరగా అడిగినవాడు {sukesha|సుకేశ భారద్వాజుడు}; అతను ఒక ఒప్పుకోలుతో మొదలుపెట్టాడు. “స్వామీ, కోసల రాకుమారుడు {hiranyanabha|హిరణ్యనాభుడు} ఒకసారి నా దగ్గరకు వచ్చి అడిగాడు: ‘భారద్వాజా, పదహారు కళల పురుషుడు నీకు తెలుసా?’ నేను ఆ యువకునితో అన్నాను: ‘నాకు ఆయన తెలియదు. తెలిస్తే నీకు ఎందుకు చెప్పను? అబద్ధం చెప్పేవాడు వేళ్ళతో సహా ఎండిపోతాడు. అందుకే నేను అబద్ధం చెప్పను.’ ఆ రాకుమారుడు మౌనంగా రథమెక్కి వెళ్ళిపోయాడు. ఇప్పుడు మిమ్మల్ని అడుగుతున్నాను: ఆ పురుషుడు ఎక్కడ ఉన్నాడు?”"],
   ["dyk", "🌱", "“Dries up to the root” — the Upaniṣad pictures a lie as a sickness of a tree: it may stand for a while, but it withers from below. Sukeśā chose to look ignorant rather than be false.", "‘వేళ్ళతో సహా ఎండిపోతాడు’ — ఉపనిషత్తు అబద్ధాన్ని చెట్టుకు వచ్చే జబ్బుగా చిత్రిస్తుంది: కొంతకాలం నిలబడినా కింది నుండి ఎండిపోతుంది. అబద్ధం చెప్పడం కంటే తెలియనివాడిలా కనిపించడమే సుకేశుడు ఎంచుకున్నాడు."]
  ],
  [
   ["h", "“Here, within the body”", "“ఇక్కడే, శరీరంలోనే”"],
   ["p", "{pippalada|Pippalāda} said: “That Person, dear one, is right here within the body, in whom these sixteen parts arise.” And he told how. The Person reflected: “When I leave, who will leave with me? When I stay, who will make me stay?” So he brought forth Breath; from Breath, faith; then space, air, light, water and earth; the senses; the mind; food; from food, strength; then tapas, the sacred verses, action, the worlds — and in the worlds, name. These are the sixteen parts.", "{pippalada|పిప్పలాదుడు} అన్నాడు: “నాయనా, ఆ పురుషుడు ఇక్కడే, ఈ శరీరంలోనే ఉన్నాడు; ఈ పదహారు కళలు ఆయనలోనే పుడతాయి.” ఎలాగో చెప్పాడు. ఆ పురుషుడు ఆలోచించాడు: “నేను వెళ్ళిపోతే నాతో ఎవరు వెళ్తారు? నేను ఉంటే నన్ను ఎవరు నిలుపుతారు?” అలా ఆయన ప్రాణాన్ని సృష్టించాడు; ప్రాణం నుండి శ్రద్ధ; తర్వాత ఆకాశం, వాయువు, తేజస్సు, నీరు, భూమి; ఇంద్రియాలు; మనసు; అన్నం; అన్నం నుండి వీర్యం (బలం); తర్వాత తపస్సు, మంత్రాలు, కర్మ, లోకాలు — లోకాల్లో నామం. ఇవే పదహారు కళలు."]
  ],
  [
   ["h", "Rivers into the sea", "సముద్రంలో కలిసే నదులు"],
   ["p", "Then he gave the image the Upaniṣad is loved for. Rivers flowing toward the ocean reach it and disappear; their names and forms are gone, and people simply say “the ocean.” In the same way, the sixteen parts of the one who truly sees flow toward the Person, reach him and disappear; their names and forms are gone, and people simply say “the Person.” Then he is without parts, and immortal.", "తర్వాత ఉపనిషత్తుకు ప్రసిద్ధి తెచ్చిన ఉపమానం చెప్పాడు. సముద్రం వైపు ప్రవహించే నదులు దాన్ని చేరి కనిపించకుండా పోతాయి; వాటి పేర్లూ రూపాలూ పోతాయి; జనం ‘సముద్రం’ అని మాత్రమే అంటారు. అలాగే నిజంగా దర్శించినవాని పదహారు కళలూ పురుషుని వైపు ప్రవహించి, ఆయనను చేరి కనుమరుగవుతాయి; వాటి పేర్లూ రూపాలూ పోతాయి; ‘పురుషుడు’ అని మాత్రమే అంటారు. అప్పుడు అతను కళలు లేనివాడు, అమృతుడు అవుతాడు."],
   ["p", "“Know that Person, in whom the parts are fixed like spokes in the hub of a wheel — know him who is to be known, so that death may not trouble you.”", "“చక్రం నాభిలో ఆకుల్లా కళలన్నీ ఎవరిలో ఇమిడి ఉన్నాయో ఆ పురుషుణ్ణి తెలుసుకోండి — తెలుసుకోవలసిన ఆయనను తెలుసుకోండి; అప్పుడు మృత్యువు మిమ్మల్ని బాధించదు.”"]
  ],
  [
   ["h", "“You are our father”", "“మీరే మా తండ్రి”"],
   ["p", "Then Pippalāda said simply: “This much I know of the highest Brahman. There is nothing beyond it.” The six students worshipped him and spoke the words with which the Upaniṣad ends:", "తర్వాత పిప్పలాదుడు సరళంగా అన్నాడు: “పరబ్రహ్మ గురించి నాకు ఇంతే తెలుసు. దీనికి మించినది ఏదీ లేదు.” ఆరుగురు శిష్యులు ఆయనను పూజించి, ఉపనిషత్తు ముగిసే మాటలు పలికారు:"],
   ["sloka", ["తే తమర్చయంతస్త్వం హి నః పితా యోఽస్మాకమవిద్యాయాః పరం పారం తారయసీతి ।", "నమః పరమఋషిభ్యో నమః పరమఋషిభ్యః ॥"], ["te tam arcayantas tvaṃ hi naḥ pitā yo 'smākam avidyāyāḥ paraṃ pāraṃ tārayasīti |", "namaḥ paramaṛṣibhyo namaḥ paramaṛṣibhyaḥ ||"], "Worshipping him, they said: “You are truly our father — you who carry us across our ignorance to the farther shore.” Salutation to the supreme seers! Salutation to the supreme seers! (Praśna Upaniṣad 6.8)", "ఆయనను పూజిస్తూ వాళ్ళు అన్నారు: “అజ్ఞానానికి ఆవలి ఒడ్డుకు మమ్మల్ని దాటించే మీరే నిజంగా మా తండ్రి.” పరమ ఋషులకు నమస్కారం! పరమ ఋషులకు నమస్కారం! (ప్రశ్నోపనిషత్తు 6.8)"],
   ["p", "Think of who is being called “father” here. In the Purāṇas, Pippalāda was the boy who never knew his own father. In the Upaniṣad, six students call him father — the one who carries them across. The orphan of the fig tree became a father to seekers.", "ఇక్కడ ‘తండ్రి’ అని ఎవరిని పిలుస్తున్నారో ఆలోచించండి. పురాణాల్లో పిప్పలాదుడు తన తండ్రిని ఎన్నడూ ఎరగని బాలుడు. ఉపనిషత్తులో ఆరుగురు శిష్యులు ఆయనను తండ్రీ — తమను దాటించేవాడు — అని పిలుస్తారు. రావిచెట్టు కింది అనాథ సాధకులకు తండ్రి అయ్యాడు."],
   ["src", "Praśna Upaniṣad, sixth question (Sukeśā Bhāradvāja: Hiraṇyanābha of Kosala and the honest “I do not know”; the Person within the body; the sixteen parts; rivers into the ocean; spokes in the hub; “nothing beyond this”; the students' worship and the closing words, 6.8).", "ప్రశ్నోపనిషత్తు, ఆరవ ప్రశ్న (సుకేశ భారద్వాజుడు: కోసల రాకుమారుడు హిరణ్యనాభుడు, నిజాయితీగా ‘నాకు తెలియదు’; శరీరంలోని పురుషుడు; పదహారు కళలు; సముద్రంలో నదులు; నాభిలో ఆకులు; ‘దీనికి మించినది లేదు’; శిష్యుల పూజ, ముగింపు మాటలు, 6.8)."]
  ]
 ],
 remember: [
  ["{sukesha|Sukeśā} told a prince “I do not know” rather than speak untruth.", "అబద్ధం చెప్పకుండా ఒక రాకుమారునికి {sukesha|సుకేశుడు} ‘నాకు తెలియదు’ అన్నాడు."],
  ["The Person of sixteen parts is within the body; the parts merge in him like rivers in the sea.", "పదహారు కళల పురుషుడు శరీరంలోనే ఉన్నాడు; సముద్రంలో నదుల్లా కళలన్నీ ఆయనలో కలుస్తాయి."],
  ["The students called {pippalada|Pippalāda} their father, who carried them across ignorance.", "అజ్ఞానాన్ని దాటించినందుకు శిష్యులు {pippalada|పిప్పలాదుణ్ణి} తమ తండ్రి అన్నారు."]
 ],
 think: ["Sukeśā admitted he did not know, and the prince left without a word. Is it hard to say “I don't know”? Why does the Upaniṣad praise it?", "సుకేశుడు తనకు తెలియదని ఒప్పుకున్నాడు; రాకుమారుడు ఒక్క మాట కూడా అనకుండా వెళ్ళిపోయాడు. ‘నాకు తెలియదు’ అనడం కష్టమా? ఉపనిషత్తు దాన్ని ఎందుకు మెచ్చుకుంటుంది?"]
},
{
 id: "ppl-10", sage: "pippalada", n: 10, order: 4610, date: "2026-11-19",
 title: "Keeper of a Veda — What Pippalāda Leaves Us", titleTe: "వేద సంరక్షకుడు — పిప్పలాదుడు మనకు మిగిల్చినది",
 src: "Viṣṇu Purāṇa, Book 3 · the Paippalāda Saṃhitā · Praśna Upaniṣad",
 who: ["pippalada", "vyasa", "sumantu", "shankara"],
 pages: [
  [
   ["p", "{pippalada|Pippalāda}'s name lives on in one more great way: a whole branch of the Atharvaveda is called after him. The Purāṇas tell how {vyasa|Vyāsa} divided the Veda and gave the Atharvaveda to his pupil {sumantu|Sumantu}, and how it then passed down from teacher to pupil and divided into branches. The Viṣṇu Purāṇa, in its third book, names a Pippalāda among the teachers in that Atharvaveda line.", "{pippalada|పిప్పలాదుని} పేరు ఇంకో గొప్ప విధంగా కూడా నిలిచి ఉంది: అథర్వవేదంలో ఒక శాఖ మొత్తానికి ఆయన పేరే. {vyasa|వ్యాసుడు} వేదాన్ని విభజించి అథర్వవేదాన్ని తన శిష్యుడు {sumantu|సుమంతునికి} ఇచ్చాడనీ, తర్వాత అది గురువు నుండి శిష్యునికి అందుతూ శాఖలుగా విడిపోయిందనీ పురాణాలు చెబుతాయి. విష్ణు పురాణం తన మూడవ అంశంలో ఆ అథర్వవేద పరంపరలోని గురువుల్లో ఒక పిప్పలాదుని పేరు చెబుతుంది."],
   ["sglink", "Vyāsa divides the Veda", "వ్యాసుడు వేదాన్ని విభజించడం", "vy-2"]
  ],
  [
   ["h", "The Paippalāda Saṃhitā", "పైప్పలాద సంహిత"],
   ["p", "Today two branches of the Atharvaveda survive: the Śaunaka and the Paippalāda. The Śaunaka text is the one most people know. The Paippalāda — “of Pippalāda's school” — was long thought lost. Then, in modern times, a birch-bark manuscript of it was found in Kashmir, and later living reciters and palm-leaf manuscripts were found in Odisha, where some families had kept chanting it for centuries. Scholars are still editing it today.", "ఈనాడు అథర్వవేదంలో రెండు శాఖలు మిగిలి ఉన్నాయి: శౌనక శాఖ, పైప్పలాద శాఖ. చాలామందికి తెలిసింది శౌనక పాఠం. పైప్పలాద — ‘పిప్పలాదుని శాఖకు చెందినది’ — చాలాకాలం పోయిందనే అనుకున్నారు. తర్వాత ఆధునిక కాలంలో కాశ్మీరులో దాని భూర్జపత్ర (బిర్చ్ బెరడు) ప్రతి దొరికింది; ఆ తర్వాత ఒడిశాలో తాటాకు ప్రతులూ, శతాబ్దాలుగా దాన్ని పఠిస్తూ వచ్చిన కుటుంబాలూ కనిపించాయి. పండితులు ఇప్పటికీ దాన్ని పరిష్కరిస్తున్నారు."],
   ["dyk", "📜", "Odisha is a neighbour of Andhra. The Paippalāda reciters there kept the text alive by memory and by palm-leaf copies — the same way Telugu families once kept their Vedas and their Bhāratam.", "ఒడిశా ఆంధ్రకు పొరుగు రాష్ట్రం. అక్కడి పైప్పలాద పండితులు జ్ఞాపకశక్తితో, తాటాకు ప్రతులతో ఆ పాఠాన్ని బతికించారు — ఒకప్పుడు తెలుగు కుటుంబాలు తమ వేదాలనూ, భారతాన్నీ కాపాడుకున్నట్టే."]
  ],
  [
   ["h", "One name, many lives", "ఒక పేరు, అనేక జీవితాలు"],
   ["p", "So who was Pippalāda? The Upaniṣad shows a calm teacher of the Atharvaveda. The Purāṇas show an orphan of the fig tree, burning with anger and then letting it go; the Śiva Purāṇa sees in him a form of Śiva himself. The Viṣṇu Purāṇa places a Pippalāda in the line of the Atharvaveda's teachers. Tradition also ascribes to him the short Garbha Upaniṣad, on the growth of a child in the womb. Whether these are one man or several who shared a name, the tradition has always held them together — and the picture they make is a true one.", "ఇంతకీ పిప్పలాదుడు ఎవరు? ఉపనిషత్తు అథర్వవేదపు ప్రశాంత గురువును చూపిస్తుంది. పురాణాలు రావిచెట్టు కింది అనాథను — కోపంతో రగిలి, దాన్ని వదిలేసినవాణ్ణి — చూపిస్తాయి; శివ పురాణం అతనిలో శివుని రూపాన్నే చూస్తుంది. విష్ణు పురాణం అథర్వవేద గురు పరంపరలో ఒక పిప్పలాదుణ్ణి నిలుపుతుంది. గర్భంలో శిశువు ఎదుగుదల గురించిన చిన్న గర్భోపనిషత్తును కూడా సంప్రదాయం ఆయనకే ఆపాదిస్తుంది. ఇవన్నీ ఒకే వ్యక్తా, ఒకే పేరున్న ఎందరో వ్యక్తులా — సంప్రదాయం ఎప్పుడూ వీటిని కలిపే చూసింది; అవి కలిసి చూపించే చిత్రం నిజమైనది."],
   ["dyk", "❓", "{shankara|Śaṅkara} says the Praśna Upaniṣad explains at length what the Muṇḍaka Upaniṣad, also of the Atharvaveda, says briefly. That is why the two are often studied together.", "అథర్వవేదానికే చెందిన ముండకోపనిషత్తు క్లుప్తంగా చెప్పినదాన్ని ప్రశ్నోపనిషత్తు విస్తరించి చెబుతుందని {shankara|శంకరాచార్యులు} అంటారు. అందుకే ఆ రెండింటినీ తరచుగా కలిపి చదువుతారు."]
  ],
  [
   ["h", "From anger to answers", "కోపం నుండి జవాబుల వరకు"],
   ["p", "Put the stories side by side and you see a whole life. A child loses everything because of a war he never saw. He grows up asking “why?” — and the first answer he reaches for is revenge. He learns, painfully, that anger turns first on the one who holds it. He lets it go. And the same mind that once wanted to burn heaven becomes the mind that patiently answers six questions about life, breath, sleep, Om and the Self — and is honest enough to say “if we know.”", "కథలను పక్కపక్కన పెడితే ఒక సంపూర్ణ జీవితం కనిపిస్తుంది. తాను ఎన్నడూ చూడని యుద్ధం వల్ల ఒక బిడ్డ సర్వం కోల్పోతాడు. ‘ఎందుకు?’ అని అడుగుతూ పెరుగుతాడు — అతనికి తొలుత తోచిన జవాబు ప్రతీకారం. కోపం ముందుగా దాన్ని పట్టుకున్నవాణ్ణే కాలుస్తుందని బాధతో నేర్చుకుంటాడు. దాన్ని వదిలేస్తాడు. ఒకప్పుడు స్వర్గాన్ని కాల్చాలనుకున్న ఆ మనసే — జీవం, ప్రాణం, నిద్ర, ఓం, ఆత్మ గురించిన ఆరు ప్రశ్నలకు ఓపికగా జవాబిచ్చే మనసు అవుతుంది — ‘మాకు తెలిస్తే’ అనగలిగేంత నిజాయితీతో."],
   ["p", "The boy who asked the trees “Where are my parents?” became the teacher who answered “Where do all creatures come from?” Every great question he answered was, in a way, his own first question, grown up.", "“నా అమ్మానాన్న ఎక్కడ?” అని చెట్లను అడిగిన బాలుడు “ప్రాణులన్నీ ఎక్కడి నుండి వస్తాయి?” అన్న ప్రశ్నకు జవాబిచ్చే గురువయ్యాడు. ఆయన జవాబిచ్చిన ప్రతి గొప్ప ప్రశ్నా — ఒక విధంగా — పెద్దదైన ఆయన తొలి ప్రశ్నే."],
   ["src", "Viṣṇu Purāṇa, Book 3 (Vyāsa's division of the Veda; the Atharvaveda through Sumantu and his line, naming a Pippalāda). The Paippalāda Saṃhitā of the Atharvaveda (Kashmir and Odisha traditions). Garbha Upaniṣad (traditionally ascribed to Pippalāda). Śaṅkara's introduction to the Praśna Upaniṣad. Brahma Purāṇa, Gautamī Māhātmya; Śiva Purāṇa, Śatarudra Saṃhitā.", "విష్ణు పురాణం, మూడవ అంశం (వ్యాసుడు వేద విభజన; సుమంతుని ద్వారా అథర్వవేద పరంపర, అందులో పిప్పలాదుని పేరు). అథర్వవేద పైప్పలాద సంహిత (కాశ్మీర, ఒడిశా సంప్రదాయాలు). గర్భోపనిషత్తు (సంప్రదాయంగా పిప్పలాదునికి ఆపాదితం). ప్రశ్నోపనిషత్తుకు శంకరుల ఉపోద్ఘాతం. బ్రహ్మ పురాణం, గౌతమీ మాహాత్మ్యం; శివ పురాణం, శతరుద్ర సంహిత."]
  ]
 ],
 remember: [
  ["The Paippalāda branch of the Atharvaveda carries {pippalada|Pippalāda}'s name.", "అథర్వవేదపు పైప్పలాద శాఖ {pippalada|పిప్పలాదుని} పేరు మోస్తుంది."],
  ["Long thought lost, it was found again in Kashmir and Odisha.", "పోయిందనుకున్న ఆ శాఖ కాశ్మీరులో, ఒడిశాలో మళ్ళీ దొరికింది."],
  ["The orphan full of anger became the patient teacher of the Praśna Upaniṣad.", "కోపంతో నిండిన అనాథ ప్రశ్నోపనిషత్తులోని ఓపిక గల గురువయ్యాడు."]
 ],
 think: ["Pippalāda's own first question was “Where are my parents?” Has a painful question in your life ever led you to learn something deep?", "పిప్పలాదుని తొలి ప్రశ్న “నా అమ్మానాన్న ఎక్కడ?” మీ జీవితంలో బాధ కలిగించిన ఒక ప్రశ్న ఎప్పుడైనా మిమ్మల్ని లోతైనదేదో నేర్చుకునేలా చేసిందా?"]
}
]);
